import {
	AdminGetUserCommand,
	CognitoIdentityProviderClient,
} from '@aws-sdk/client-cognito-identity-provider';
import { DynamoDBClient, GetItemCommand } from '@aws-sdk/client-dynamodb';
import { getTenantContext, createResponse } from 'tenant-utils';

const dynamodb = new DynamoDBClient({ region: process.env.AWS_REGION });

/**
 * Domain Restriction — keep in sync with all inline implementations:
 *   - packages/admin-portal/cdk/lambda/userslist/post.mjs
 *   - packages/admin-portal/cdk/lambda/importusersworker/index.mjs
 *   - packages/service/cdk/lambda/amfa/utils/signUp.mjs
 *   - packages/service/cdk/lambda/checkuser/checkuser.mjs
 *   - CognitoAdSync/sync-engine.js
 *
 * @param {string} email - User email address
 * @param {string[]} allowedDomains - Permitted domains (empty/null = allow all)
 * @returns {{ allowed: boolean, domain?: string, error?: string }}
 */
function validateEmailDomain(email, allowedDomains) {
  if (!allowedDomains || allowedDomains.length === 0) return { allowed: true };
  const domain = email.split('@')[1]?.toLowerCase();
  if (!domain) return { allowed: false, error: 'Invalid email format' };
  const allowed = allowedDomains.some(d => d.toLowerCase() === domain);
  if (!allowed) return { allowed: false, domain, error: 'Your login domain is not permitted.' };
  return { allowed: true, domain };
}

const validateInputParams = (event) => {
	return event.email.trim().length > 0 && event.apti.trim().length > 0;
};

const getUser = async (payload, cognito, userPoolId, tenantId) => {

	const command = new AdminGetUserCommand({
		Username: payload.email,
		UserPoolId: userPoolId,
	});
	try {
		const user = await cognito.send(command);
		console.log(`[Tenant: ${tenantId}] get user:`, user);
		return user;
	} catch (error) {
		console.log(`[Tenant: ${tenantId}] error in get user:`, error);
		console.log(`[Tenant: ${tenantId}] error code:`, error.code);
		throw error;
	}
}

// lambda for rest api /checkuser
export const handler = async (event) => {
	console.log(event);

	try {
		// Extract tenant context from request
		const tenantContext = await getTenantContext(event);
		console.log('Tenant context:', tenantContext);

		const payload = JSON.parse(event.body);

		if (validateInputParams(payload)) {
			// Domain Restriction: check email domain BEFORE checking user existence
			// This blocks registration at the very first step for disallowed domains
			try {
				const configTableName = tenantContext.tableNames?.amfaConfigTable || process.env.AMFACONFIG_TABLE || 'amfa-configtable';
				const configResult = await dynamodb.send(new GetItemCommand({
					TableName: configTableName,
					Key: { id: { S: tenantContext.tenantId }, configtype: { S: 'amfaConfigs' } },
				}));
				if (configResult.Item?.value?.S) {
					const config = JSON.parse(configResult.Item.value.S);

					// Registration kill switch: /checkuser is only called by the
					// registration flow, so block at the very first step.
					// Keep in sync with: amfaSteps.mjs, signUp.mjs
					if (config.enable_user_registration !== true) {
						return createResponse(403, { message: 'User registration is disabled.' }, tenantContext.tenantId);
					}

					const tenantDomainCheck = validateEmailDomain(payload.email, config.allowed_domains);
					if (!tenantDomainCheck.allowed) {
						return createResponse(403, { message: tenantDomainCheck.error }, tenantContext.tenantId);
					}

					// Also check policy-level restriction for the default registration group
					const defaultGroup = config.user_registration_default_group;
					if (defaultGroup) {
						const policiesResult = await dynamodb.send(new GetItemCommand({
							TableName: configTableName,
							Key: { id: { S: tenantContext.tenantId }, configtype: { S: 'amfaPolicies' } },
						}));
						if (policiesResult.Item?.value?.S) {
							const policies = JSON.parse(policiesResult.Item.value.S);
							const groupPolicy = policies?.[defaultGroup];
							if (groupPolicy?.allowed_domains?.length > 0) {
								const policyDomainCheck = validateEmailDomain(payload.email, groupPolicy.allowed_domains);
								if (!policyDomainCheck.allowed) {
									return createResponse(403, { message: policyDomainCheck.error }, tenantContext.tenantId);
								}
							}
						}
					}
				}
			} catch (domainErr) {
				console.error(`[Tenant: ${tenantContext.tenantId}] Domain restriction check failed:`, domainErr.message);
				return createResponse(500, { message: 'Unable to verify domain restrictions. Please try again.' }, tenantContext.tenantId);
			}

			const cognito = new CognitoIdentityProviderClient({
				region: process.env.AWS_REGION,
			});

			try {

				const user = await getUser(payload, cognito, tenantContext.userPoolId, tenantContext.tenantId);
				console.log(`[Tenant: ${tenantContext.tenantId}] find user:`, user);

				if (user) {
					return createResponse(400, { message: 'Username already exists' }, tenantContext.tenantId);
				}
			} catch (err) {
				console.error(`[Tenant: ${tenantContext.tenantId}] Error:`, err);

				if (err.code === 'UserNotFoundException' || err.message === 'User does not exist.') {
					return createResponse(200, { message: 'username is available' }, tenantContext.tenantId);
				}
				const error = err.message ? err.message : { message: "error while checking email signup" }
				return createResponse(400, error, tenantContext.tenantId);
			}
		} else {
			return createResponse(500, { message: 'incoming params error.' }, tenantContext.tenantId);
		}

	} catch (e) {
		console.log('Catch an error: ', e);
		
		// Try to get tenant ID for error response
		let tenantId = null;
		try {
			const tenantContext = await getTenantContext(event);
			tenantId = tenantContext.tenantId;
		} catch (tenantError) {
			console.log('Could not extract tenant ID for error response:', tenantError.message);
		}
		
		return createResponse(500, { message: 'check username error' }, tenantId);
	}
};
